mapper.select:
SELECT a.id AS id, a.code AS code, a.name AS name, asset_category.code AS asset_category_code, asset_category.name AS asset_category_name, department.name AS department_name, a.status_code AS status_code, asset_status.name AS status_name, a.note AS note, a.created_at AS created_at, a.updated_at AS updated_at FROM assets a
WHERE a.company_id = #{companyId} AND a.is_deleted = FALSE
AND a.code LIKE CONCAT('%', #{assetSearchForm.assetCode}, '%')
AND a.name LIKE CONCAT('%', #{assetSearchForm.assetName}, '%')
AND a.asset_category_value_id = #{assetSearchForm.assetCategoryValueId}
AND a.department_id = #{assetSearchForm.departmentId}
AND a.status_code = #{assetSearchForm.statusCode}
ORDER BY a.created_at DESC, a.id DESC

SELECT

FROM assets a

WHERE a.id = #{id}
    AND a.company_id = #{companyId}
    AND a.is_deleted = FALSE

SELECT EXISTS(
    SELECT 1
    FROM departments department
    WHERE department.id = #{departmentId}
        AND department.company_id = #{companyId}
        AND department.is_deleted = FALSE
)

SELECT EXISTS(
    SELECT 1
    FROM assets a
    WHERE a.company_id = #{companyId}
        AND a.code = #{code}
)

SELECT EXISTS(
    SELECT 1
    FROM assets a
    WHERE a.company_id = #{companyId}
        AND a.code = #{code}
        AND a.id != #{id}
)

mapper.update:
UPDATE assets
SET status_code = #{statusCode},
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND is_deleted = FALSE

UPDATE assets
SET is_deleted = TRUE,
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND is_deleted = FALSE
